import {createHash} from 'node:crypto';
import {readFileSync} from 'node:fs';
import {pathToFileURL} from 'node:url';
const root=process.cwd();
const {parseWordDat:before}=await import(pathToFileURL(root+'/packages/pal-extract/src/io/__quality_word_before.ts').href);
const {parseWordDat:after}=await import(pathToFileURL(root+'/packages/pal-extract/src/io/word.ts').href);
const raw=new Uint8Array(readFileSync(root+'/data/raw/WORD.DAT'));
const sha=(bytes)=>createHash('sha256').update(bytes).digest('hex');
const cases=[0,1,9,10,11,100,5649,5650].map(n=>({name:'raw-prefix-'+n,bytes:raw.slice(0,n)}));
const extra=new Uint8Array(raw.length+1);extra.set(raw);extra[raw.length]=32;cases.push({name:'extra-byte',bytes:extra});
const framed=new Uint8Array(raw.length+8).fill(0xa5);framed.set(raw,4);cases.push({name:'nonzero-byteOffset',bytes:framed.subarray(4,4+raw.length)});
const markers=raw.slice();markers.fill(32,0,10);markers.set([65,32,67,49],0);markers.set(new TextEncoder().encode('BBBBBBBBBB'),360);cases.push({name:'inner-space-marker-and-full-record',bytes:markers});
const results=cases.map(({name,bytes})=>{const input=sha(bytes);const b=JSON.stringify(before(bytes));const a=JSON.stringify(after(bytes));if(a!==b||sha(bytes)!==input)throw new Error('behavior/ownership mismatch '+name);return {name,inputSha256:input,outputSha256:sha(a),equal:true,inputUnchanged:true};});
process.stdout.write(JSON.stringify({results,allEqual:true,limits:'Finite old-implementation regression,not an independent correctness oracle;short/extra inputs retain the previous policy without newly approving that input domain.'})+'\n');
